//! FIND-631 / ADR-0060 D8(b): on-disk compatibility of a `v0.9.0` database
//! under the `v0.10.0` line.
//!
//! The fixture under `tests/fixtures/v0.9.0/db/` was generated by the
//! `vanta-cli` binary built from the `v0.9.0` git tag — see
//! `dev-tools/scripts/gen-fixture-v090.ps1` and `MANIFEST.json` for the exact
//! commands. Every test copies the fixture to a tempdir before opening it:
//! the fixture on disk is never mutated (one test re-verifies the sha256 of
//! each file against the manifest).
// ponytail: test harness unwraps with documented invariants; documented per-call.
#![allow(clippy::expect_used, clippy::unwrap_used)]

use serde_json::Value;
use sha2::{Digest, Sha256};
use std::fs;
use std::path::{Path, PathBuf};
use tempfile::TempDir;
use vantadb::migration::MigrationEngine;
use vantadb::{Config, DistanceMetric, Embedded, Error, Header, MemoryInput, MemorySearchRequest};

const FIXTURE_DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/v0.9.0");

fn manifest() -> Value {
    let text = fs::read_to_string(Path::new(FIXTURE_DIR).join("MANIFEST.json"))
        .expect("MANIFEST.json readable");
    serde_json::from_str(&text).expect("MANIFEST.json parses")
}

fn copy_dir(src: &Path, dst: &Path) {
    fs::create_dir_all(dst).expect("mkdir");
    for entry in fs::read_dir(src).expect("readdir") {
        let entry = entry.expect("entry");
        let to = dst.join(entry.file_name());
        if entry.file_type().expect("ft").is_dir() {
            copy_dir(&entry.path(), &to);
        } else {
            fs::copy(entry.path(), &to).expect("copy");
        }
    }
}

/// Fresh tempdir containing a copy of the fixture database root
/// (`<tmp>/db` mirrors `tests/fixtures/v0.9.0/db`).
fn fixture_copy() -> (TempDir, PathBuf) {
    let tmp = TempDir::new().expect("tempdir");
    let dst = tmp.path().join("db");
    copy_dir(&Path::new(FIXTURE_DIR).join("db"), &dst);
    (tmp, dst)
}

fn sha256_hex(path: &Path) -> String {
    let bytes = fs::read(path).expect("read for sha256");
    let digest = Sha256::digest(&bytes);
    digest.iter().map(|b| format!("{b:02x}")).collect()
}

/// Map of relative path -> sha256 for every file under `root` (sorted).
fn dir_hashes(root: &Path) -> Vec<(String, String)> {
    let mut out = Vec::new();
    let mut stack = vec![root.to_path_buf()];
    while let Some(dir) = stack.pop() {
        for entry in fs::read_dir(&dir).expect("readdir") {
            let entry = entry.expect("entry");
            let path = entry.path();
            if entry.file_type().expect("ft").is_dir() {
                stack.push(path);
            } else {
                let name = entry.file_name().to_string_lossy().into_owned();
                // Held under an exclusive OS lock while the db is open.
                if name == ".vanta.lock" || name == "lock" {
                    continue;
                }
                let rel = path
                    .strip_prefix(root)
                    .expect("under root")
                    .to_string_lossy()
                    .replace('\\', "/");
                out.push((rel, sha256_hex(&path)));
            }
        }
    }
    out.sort();
    out
}

fn expected_keys(m: &Value, ns: &str) -> Vec<String> {
    m["expected"]["namespaces"][ns]
        .as_array()
        .expect("namespace array")
        .iter()
        .map(|k| k.as_str().expect("key str").to_string())
        .collect()
}

fn open_and_check_contents(db_path: &Path, m: &Value) -> Embedded {
    open_and_check_contents_exact(db_path, m, false)
}

/// `exact_keys` asserts the namespace key set equals the manifest exactly
/// (open-in-place test); with `false` it asserts the manifest keys are a
/// subset (used after the test itself wrote new records).
fn open_and_check_contents_exact(db_path: &Path, m: &Value, exact_keys: bool) -> Embedded {
    let db = Embedded::open(db_path).expect("v0.10.0 opens a v0.9.0 database in place");
    for ns in ["docs", "notes"] {
        let keys = expected_keys(m, ns);
        let page = db.list(ns, Default::default()).expect("list namespace");
        let got: Vec<String> = page.records.iter().map(|r| r.key.clone()).collect();
        if exact_keys {
            let mut got = got.clone();
            got.sort();
            let mut want = keys.clone();
            want.sort();
            assert_eq!(got, want, "namespace {ns} key set must match the manifest");
        } else {
            for key in &keys {
                assert!(
                    got.contains(key),
                    "namespace {ns} must still contain {key}; got {got:?}"
                );
            }
        }
        for key in &keys {
            let rec = db
                .get(ns, key)
                .expect("get succeeds")
                .unwrap_or_else(|| panic!("{ns}/{key} present"));
            if let Some(expected) = m["expected"]["payloads"][format!("{ns}/{key}")].as_str() {
                assert_eq!(rec.payload, expected, "{ns}/{key} payload unchanged");
            }
        }
    }
    // The record deleted by the v0.9.0 CLI stays deleted.
    for key in m["expected"]["deleted_keys"]["docs"]
        .as_array()
        .expect("deleted keys")
    {
        let key = key.as_str().expect("str");
        assert!(
            db.get("docs", key).expect("get").is_none(),
            "deleted key docs/{key} must stay absent"
        );
    }
    db
}

#[test]
fn compat_v090_fixture_matches_manifest_sha256() {
    // Guards fixture integrity: every file recorded by the generator still
    // hashes identically, so no test (or EOL normalisation) mutated the bytes.
    let m = manifest();
    let files = m["files_sha256"].as_object().expect("files map");
    assert!(!files.is_empty(), "manifest records at least one file");
    for (rel, sha) in files {
        let path = Path::new(FIXTURE_DIR).join(rel);
        assert_eq!(
            &sha256_hex(&path),
            sha.as_str().expect("sha str"),
            "{rel} hash drifted from the generated fixture"
        );
    }
}

#[test]
fn compat_v090_open_in_place_reads_all_records() {
    let m = manifest();
    let (_tmp, db_path) = fixture_copy();
    let db = open_and_check_contents_exact(&db_path, &m, true);
    db.close().expect("clean close");
}

#[test]
fn compat_v090_search_text_and_vector() {
    let m = manifest();
    let (_tmp, db_path) = fixture_copy();
    let db = open_and_check_contents(&db_path, &m);

    // Text search (BM25 over the v0.9.0-persisted text index state).
    let text_query = m["expected"]["text_query"].as_str().expect("text query");
    let hits = db
        .search(MemorySearchRequest {
            namespace: "docs".into(),
            text_query: Some(text_query.into()),
            top_k: 10,
            ..Default::default()
        })
        .expect("text search over v0.9.0 base");
    let hit_keys: Vec<&str> = hits.iter().map(|h| h.record.key.as_str()).collect();
    let mut want_keys: Vec<&str> = m["expected"]["text_hits_docs"]
        .as_array()
        .expect("text hits")
        .iter()
        .map(|v| v.as_str().expect("str"))
        .collect();
    want_keys.sort_unstable();
    let mut got_sorted = hit_keys.clone();
    got_sorted.sort_unstable();
    assert_eq!(
        got_sorted, want_keys,
        "text search for {text_query:?} must return exactly the expected docs keys"
    );

    // Dense vector search over the v0.9.0 HNSW image.
    let query: Vec<f32> = m["expected"]["vector_query"]
        .as_array()
        .expect("vector")
        .iter()
        .map(|v| v.as_f64().expect("f64") as f32)
        .collect();
    let hits = db
        .search(MemorySearchRequest {
            namespace: "docs".into(),
            query_vector: query,
            distance_metric: DistanceMetric::Cosine,
            top_k: 3,
            ..Default::default()
        })
        .expect("vector search over v0.9.0 base");
    assert!(
        hits.iter().any(|h| h.record.key == "doc1"),
        "vector search nearest to doc1's vector must surface doc1; got {:?}",
        hits.iter().map(|h| &h.record.key).collect::<Vec<_>>()
    );
    db.close().expect("close");
}

#[test]
fn compat_v090_write_reopen_roundtrip() {
    let m = manifest();
    let (_tmp, db_path) = fixture_copy();
    {
        let db = Embedded::open(&db_path).expect("open for write");
        db.put(
            MemoryInput::new("docs", "doc_new_v010", "written by v0.10.0 line")
                .with_vector(vec![0.15, 0.22, 0.28, 0.35]),
        )
        .expect("put on v0.9.0 base");
        db.close().expect("close");
    }
    let db = open_and_check_contents(&db_path, &m);
    let rec = db
        .get("docs", "doc_new_v010")
        .expect("get")
        .expect("new record persists across reopen");
    assert_eq!(rec.payload, "written by v0.10.0 line");
    db.close().expect("close");
}

#[test]
fn compat_v090_integrity_clean_and_no_migration_planned() {
    let (_tmp, db_path) = fixture_copy();
    let engine = MigrationEngine::new(&db_path);
    let issues = engine.check_integrity().expect("integrity check runs");
    assert!(
        issues.is_empty(),
        "v0.9.0 base must report zero issues: {issues:?}"
    );
    let plans = engine.plan_all().expect("plan_all runs");
    assert!(
        plans.is_empty(),
        "no migration may be planned for a v0.9.0 base: {plans:?}"
    );
}

#[test]
fn compat_v090_index_state_self_heals_and_is_idempotent() {
    let (_tmp, db_path) = fixture_copy();
    // Drop the persisted HNSW image: the engine must rebuild it from the
    // VantaFile at open (ADR-0060 inventory: `None` → rebuild), transparently.
    let index_path = db_path.join("data").join("vector_index.bin");
    if index_path.exists() {
        fs::remove_file(&index_path).expect("drop vector_index.bin");
    }
    let db = Embedded::open(&db_path).expect("open rebuilds missing index state");
    let hits = db
        .search(MemorySearchRequest {
            namespace: "docs".into(),
            query_vector: vec![0.10, 0.20, 0.30, 0.40],
            distance_metric: DistanceMetric::Cosine,
            top_k: 3,
            ..Default::default()
        })
        .expect("vector search after forced index rebuild");
    assert!(
        hits.iter().any(|h| h.record.key == "doc1"),
        "rebuilt index must answer correctly"
    );
    // ADR-0060 D8(b): a forced secondary-state rebuild converges and a re-run
    // is a no-op — the reconciliation is idempotent. Observable check: after
    // the first explicit reconcile, hashing every file must not change.
    db.ensure_indexes_current().expect("first reconcile");
    let snapshot = dir_hashes(&db_path);
    db.ensure_indexes_current()
        .expect("second reconcile is a no-op");
    assert_eq!(
        dir_hashes(&db_path),
        snapshot,
        "idempotent reconcile must not rewrite any persisted state"
    );
    db.close().expect("close");
}

#[cfg(feature = "encryption")]
#[test]
fn compat_v090_encryption_key_keeps_plaintext_database_plaintext() {
    // ADR-0057 D7 / ADR-0060 D6: a key configured against an existing
    // plaintext database opens it plaintext with a warning — never implicit
    // re-encryption. No `encryption.registry` is created and artefact
    // versions stay on the plaintext lineage.
    let (_tmp, db_path) = fixture_copy();
    let mut cfg = Config::in_memory().with_storage_path(db_path.display().to_string());
    cfg.encryption_key = Some("00".repeat(32));
    {
        let db = Embedded::open_with_config(cfg).expect("keyed open of plaintext base");
        db.put(MemoryInput::new(
            "docs",
            "doc_keyed",
            "written under configured key",
        ))
        .expect("write under configured key");
        db.close().expect("close");
    }
    assert!(
        !db_path.join("data").join("encryption.registry").exists(),
        "no encryption.registry may be created for a plaintext v0.9.0 base"
    );
    let data = db_path.join("data");
    let vfile = fs::read_dir(&data)
        .expect("readdir")
        .filter_map(|e| e.ok().map(|e| e.path()))
        .find(|p| {
            p.file_name()
                .map(|n| n.to_string_lossy().starts_with("vstore_L"))
                .unwrap_or(false)
        })
        .expect("a vstore_L*.vanta segment exists");
    let header = Header::deserialize(&fs::read(vfile).expect("read vfile")).expect("VFLE header");
    assert_eq!(header.magic, *b"VFLE");
    assert_eq!(
        header.format_version,
        vantadb::VFILE_VERSION,
        "VantaFile stays on the plaintext version"
    );
    let wal = fs::read_dir(&data)
        .expect("readdir")
        .filter_map(|e| e.ok().map(|e| e.path()))
        .find(|p| {
            let n = p
                .file_name()
                .map(|n| n.to_string_lossy().into_owned())
                .unwrap_or_default();
            n == "vanta.wal" || (n.starts_with("vanta.shard") && n.ends_with(".wal"))
        })
        .expect("live WAL segment exists");
    let header = Header::deserialize(&fs::read(wal).expect("read wal")).expect("VWAL header");
    assert_eq!(header.magic, *b"VWAL");
    assert_eq!(
        header.format_version,
        vantadb::WAL_FORMAT_VERSION,
        "WAL stays on the plaintext version"
    );
    let index = data.join("vector_index.bin");
    if index.exists() {
        let header =
            Header::deserialize(&fs::read(index).expect("read index")).expect("VNDX header");
        assert_eq!(header.magic, *b"VNDX");
        assert_eq!(
            header.format_version,
            vantadb::VECTOR_INDEX_VERSION,
            "index stays on the plaintext version"
        );
    }
}

#[test]
fn compat_v090_future_version_is_typed_error_never_panic() {
    // ADR-0060 D7: a v0.9.0 artefact doctored to a version newer than this
    // build must produce a typed error naming what was found — never
    // "corrupt" and never a panic.
    //
    // Which typed variant depends on the build: without `encryption` the
    // range check fires `IncompatibleFormat { found_version }`; with it,
    // `detect_encryption_mode` classifies any version above the plaintext
    // one as an encrypted artefact and the open fails closed with
    // `EncryptionKeyRequired` (FIND-585/ADR-0057 R-7) before the artefact's
    // own version check runs. Both are typed refusals; the ADR names the
    // first, the second is the same guarantee through the encryption gate.
    let (_tmp, db_path) = fixture_copy();
    let data = db_path.join("data");
    let vfile = fs::read_dir(&data)
        .expect("readdir")
        .filter_map(|e| e.ok().map(|e| e.path()))
        .find(|p| {
            p.file_name()
                .map(|n| n.to_string_lossy().starts_with("vstore_L"))
                .unwrap_or(false)
        })
        .expect("vstore segment");
    let mut bytes = fs::read(&vfile).expect("read vfile");
    bytes[4..6].copy_from_slice(&u16::MAX.to_le_bytes()); // format_version := 65535
    fs::write(&vfile, bytes).expect("write doctored vfile");

    match Embedded::open(&db_path) {
        Err(Error::IncompatibleFormat { found_version, .. }) => {
            assert_eq!(found_version, u16::MAX, "error names the found version");
        }
        Err(Error::EncryptionKeyRequired { .. }) => {}
        Err(other) => panic!("expected a typed refusal, got {other:?}"),
        Ok(_) => panic!("a future artefact version must not open"),
    }
}

/// ADR-0060 D5 / D8(b): rollback — the fixture after a v0.10.0 open+write must
/// still be readable by the *v0.9.0* binary.
///
/// Automated only when a v0.9.0 `vanta-cli` binary is provided via the
/// `VANTADB_V090_CLI` environment variable (e.g. the one built by
/// `gen-fixture-v090.ps1`); the test skips loudly otherwise — a full build of
/// the tag inside a unit test is out of scope.
#[test]
fn compat_v090_rollback_fixture_reopened_by_v090_binary() {
    let Some(cli) = std::env::var_os("VANTADB_V090_CLI") else {
        eprintln!(
            "SKIP compat_v090_rollback_fixture_reopened_by_v090_binary: \
             set VANTADB_V090_CLI to a v0.9.0 vanta-cli binary to run the \
             cross-version rollback check"
        );
        return;
    };
    let (_tmp, db_path) = fixture_copy();
    {
        let db = Embedded::open(&db_path).expect("v0.10.0 open+write");
        db.put(MemoryInput::new(
            "notes",
            "note_rollback",
            "written by v0.10.0",
        ))
        .expect("write");
        db.close().expect("close");
    }
    // The v0.9.0 binary must still read the mutated base: plaintext artefacts
    // written by v0.10.0 carry versions v0.9.0 already accepts (ADR-0060 D5).
    let out = std::process::Command::new(cli)
        .args([
            "--db",
            &db_path.display().to_string(),
            "get",
            "--namespace",
            "notes",
            "--key",
            "note_rollback",
        ])
        .output()
        .expect("spawn v0.9.0 vanta-cli");
    assert!(
        out.status.success(),
        "v0.9.0 binary must open the v0.10.0-written base; stderr: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(
        String::from_utf8_lossy(&out.stdout).contains("written by v0.10.0"),
        "v0.9.0 binary must read the record written by v0.10.0"
    );
}
